"/?p=admin&year='.h($year).'&type='.h($type).'&district='.h($district).'&refresh=1">Refresh FIRST event list</a></p><form method="post" action="/?p=event">'.csrf().'<input type="hidden" name="year" value="'.h($year).'"><label>Event<select name="event_code" required><option value="">Choose an event</option>';foreach($filtered as $item)echo '<option value="'.h($item['code']).'">'.h($item['name']).' — '.h($item['location']).'</option>';echo '</select></label><button'.(!$filtered?' disabled':'').'>Select event</button></form></section><section><h2>Add user</h2><form method="post" action="/?p=user">'.csrf().'<label>Username<input name="name" required></label><label>Password<input type="password" name="password" minlength="10" required></label><label>Role<select name="role"><option>scout</option><option>pit</option><option>drive</option><option>mentor</option><option>admin</option></select></label><label>Position<select name="position"><option value="">None</option>';foreach(['R1','R2','R3','B1','B2','B3'] as $x)echo '<option>'.h($x).'</option>';echo '</select></label><button>Create account</button></form></section></div>';if($e)echo '<section><h2>Import schedule</h2><p>CSV columns: match,r1,r2,r3,b1,b2,b3. Existing submitted slots are protected.</p><form method="post" action="/?p=import" enctype="multipart/form-data">'.csrf().'<input type="file" name="csv" accept=".csv" required><button>Import CSV</button></form></section>';if($e){$tc=query('SELECT count(*) FROM teams WHERE event_id=?',[$e['id']])->fetchColumn();$mc=query('SELECT count(*) FROM matches WHERE event_id=?',[$e['id']])->fetchColumn();echo '<section><h2>Active event</h2><p>'.h($e['name']).' · '.h($tc).' teams · '.h($mc).' qualification matches</p>';if(preg_match('/^(\d{4})([a-z0-9]+)$/',$e['event_key']??''))echo '<form method="post" action="/?p=refresh_event">'.csrf().'<button>Refresh official data</button></form>';echo '</section>';}echo '<h2>Users</h2>';foreach(query('SELECT name,role,position FROM users ORDER BY name')->fetchAll(PDO::FETCH_ASSOC) as $u)echo '<p>'.h($u['name']).' · '.h($u['role']).' '.h($u['position']).'</p>';endpage();}
elseif($p==='matches'){page('Match schedule');if($e){echo '<div class="scroll"><table><thead><tr><th>Match</th>';foreach(['R1','R2','R3','B1','B2','B3'] as $pos)echo '<th>'.h($pos).'</th>';echo '</tr></thead><tbody>';foreach(query('SELECT * FROM matches WHERE event_id=? ORDER BY match_number',[$e['id']]) as $m){echo '<tr><th>Q'.h($m['match_number']).'</th>';foreach(['R1','R2','R3','B1','B2','B3'] as $pos){$s=query('SELECT * FROM slots WHERE match_id=? AND position=?',[$m['id'],$pos])->fetch(PDO::FETCH_ASSOC);echo '<td>'.($s?'<a href="/?p=scout&id='.h($s['id']).'">'.h($s['team_number']).'</a><small>'.h($s['status']).'</small>':'—').'</td>';}echo '</tr>';}echo '</tbody></table></div>';}endpage();}
elseif($p==='scout'){ $s=query('SELECT s.*,m.match_number,m.event_id,m.video_url,sc.data,sc.version,sc.status AS record_status FROM slots s JOIN matches m ON m.id=s.match_id LEFT JOIN scouting sc ON sc.slot_id=s.id WHERE s.id=?',[$_GET['id']??''])->fetch(PDO::FETCH_ASSOC);if(!$s||!$e||$s['event_id']!==$e['id']){http_response_code(404);exit('Slot not found');}$d=json_decode($s['data']??'{}',true);page('Q'.$s['match_number'].' · '.$s['position'].' · Team '.$s['team_number']);if($s['video_url'])echo '<p><a href="'.h($s['video_url']).'">Watch match video</a></p>';if($s['record_status']==='submitted'&&!role('admin','mentor')){echo '<p>Submitted and locked. Ask a mentor to correct this record.</p>';foreach($d as $k=>$v)echo '<p><b>'.h($k).':</b> '.h($v).'</p>';}else{echo '<form method="post" action="/?p=scout">'.csrf().'<input type="hidden" name="slot" value="'.h($s['id']).'"><input type="hidden" name="version" value="'.h($s['version']??0).'">';foreach(['auto_score'=>'Autonomous notes / count','teleop_score'=>'Teleop notes / count','endgame'=>'Endgame','defense'=>'Defense','penalties'=>'Penalties','breakdown'=>'Breakdown / reliability','notes'=>'Observations'] as $k=>$label)echo '<label>'.h($label).'<textarea name="'.h($k).'">'.field($d,$k).'</textarea></label>';echo '<button>Save draft</button> <button name="submit" value="1">Submit</button></form>';}endpage();}
elseif($p==='teams'){page('Teams');if($e){echo '<p>'.h($e['name']).' · Browse teams and start pit scouting.</p><div class="team-grid">';foreach(query('SELECT t.number,t.name,ph.uploaded_at,(SELECT count(*) FROM scouting sc JOIN slots s ON s.id=sc.slot_id JOIN matches m ON m.id=s.match_id WHERE m.event_id=t.event_id AND s.team_number=t.number AND sc.status=\'submitted\') AS reports FROM teams t LEFT JOIN team_photos ph ON ph.event_id=t.event_id AND ph.team_number=t.number WHERE t.event_id=? ORDER BY t.number',[$e['id']]) as $t){$n=h($t['number']);echo '<article class="team-card">';if($t['uploaded_at'])echo '<img class="team-photo" src="/?p=robot_photo&n='.$n.'&v='.rawurlencode($t['uploaded_at']).'" alt="Robot photo for team '.$n.'" loading="lazy">';else echo '<div class="team-photo placeholder" aria-label="No robot photo yet">Robot photo</div>';echo '<div class="team-card-body"><h2><a href="/?p=team&n='.$n.'">'.$n.' · '.($t['name']?h($t['name']):'Unnamed team').'</a></h2><p>'.h($t['reports']).' match reports</p><a class="button" href="/?p=pit&n='.$n.'">Pit Scout</a></div></article>';}echo '</div>';}endpage();}
elseif($p==='team'||$p==='pit'){ $n=(int)($_GET['n']??0);if(!$e||!$n)go('teams');$team=query('SELECT number,name FROM teams WHERE event_id=? AND number=?',[$e['id'],$n])->fetch(PDO::FETCH_ASSOC);if(!$team){http_response_code(404);exit('Team not found');}$record=query('SELECT * FROM pit WHERE event_id=? AND team_number=?',[$e['id'],$n])->fetch(PDO::FETCH_ASSOC);$d=json_decode($record['data']??'{}',true);$photo=query('SELECT uploaded_at FROM team_photos WHERE event_id=? AND team_number=?',[$e['id'],$n])->fetch(PDO::FETCH_ASSOC);page('Team '.$n.' · '.($team['name']?:'Unnamed team'));if($p==='pit'){echo '<section class="photo-widget"><h2>Robot photo</h2>';if($photo)echo '<img class="pit-photo" src="/?p=robot_photo&n='.h($n).'&v='.rawurlencode($photo['uploaded_at']).'" alt="Robot photo for team '.h($n).'">';else echo '<div class="pit-photo placeholder">Add a robot photo</div>';echo '<form method="post" action="/?p=upload_photo" enctype="multipart/form-data">'.csrf().'<input type="hidden" name="team" value="'.h($n).'"><label>Choose robot photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><button>Upload photo</button><small>JPEG, PNG, or WebP · up to 4 MB</small></form></section><h2>Pit scouting</h2><form method="post" action="/?p=pit">'.csrf().'<input type="hidden" name="team" value="'.h($n).'">';foreach(['robot'=>'Robot identity','drivetrain'=>'Drivetrain','dimensions'=>'Dimensions','weight'=>'Weight','mechanisms'=>'Mechanisms','scoring'=>'Scoring capabilities','autonomous'=>'Autonomous','endgame'=>'Endgame','strategy'=>'Preferred strategy','reliability'=>'Reliability','requirements'=>'Special requirements','notes'=>'Notes'] as $k=>$label)echo '<label>'.h($label).'<textarea name="'.h($k).'">'.field($d,$k).'</textarea></label>';echo '<button>Save pit record</button></form><p><a href="/?p=team&n='.h($n).'">View team profile</a></p>';}else{echo '<p><a class="button" href="/?p=pit&n='.h($n).'">Pit Scout</a></p>';if($photo)echo '<img class="pit-photo" src="/?p=robot_photo&n='.h($n).'&v='.rawurlencode($photo['uploaded_at']).'" alt="Robot photo for team '.h($n).'">';echo '<h2>Pit notes</h2><section>';foreach($d as $key=>$value)if($value!=='')echo '<p><b>'.h(ucfirst($key)).':</b> '.h($value).'</p>';if(!$d)echo '<p>No pit record yet.</p>';echo '</section><h2>Match reports</h2>';foreach(query('SELECT m.match_number,s.position,sc.data FROM slots s JOIN matches m ON m.id=s.match_id JOIN scouting sc ON sc.slot_id=s.id WHERE m.event_id=? AND s.team_number=? AND sc.status=\'submitted\' ORDER BY m.match_number',[$e['id'],$n]) as $r){$v=json_decode($r['data'],true);echo '<section><b>Q'.h($r['match_number']).' '.h($r['position']).'</b><p>'.h($v['notes']??'').'</p></section>';}}endpage();}
elseif($p==='picks'){page('Alliance pick list');if($e){foreach(query('SELECT p.*,t.name FROM picklist p JOIN teams t ON t.event_id=p.event_id AND t.number=p.team_number WHERE p.event_id=? ORDER BY p.rank,p.team_number',[$e['id']]) as $x)echo '<section><b>Pick '.h($x['rank']).' · Team '.h($x['team_number']).'</b> '.($x['do_not_pick']?'⛔ Do not pick':'').'<p>'.h($x['note']).'</p></section>';if(role('admin','mentor','drive')){echo '<h2>Add or update pick</h2><form method="post" action="/?p=pick">'.csrf().'<label>Team<select name="team">';foreach(query('SELECT number FROM teams WHERE event_id=? ORDER BY number',[$e['id']]) as $t)echo '<option>'.h($t['number']).'</option>';echo '</select></label><label>Desired pick number<input name="rank" type="number" min="1" required></label><label>Note<input name="note"></label><label><input type="checkbox" name="dnp"> Do not pick</label><button>Save</button></form>';}}endpage();}
else go('home');
